proDetailPlannerPrompt.responseSchema:
{
  "type": "object",
  "description": "Detail Planner output: user-facing response + plan + optional goal draft",
  "required": [
    "uiIntent",
    "reasoningTrace"
  ],
  "properties": {
    "reasoningTrace": {
      "type": "string",
      "description": "Internal reasoning: mode determination, plan decisions, user signals, trade-offs, guardrails applied. NOT user-facing — for logging and audit."
    },
    "assistantText": {
      "type": "string",
      "description": "Execution log for chatHistory continuity — next-turn LLM reads this to know what was done. MUST include: (1) all tool calls this turn as `toolName([inputs]) → result`, (2) all mapping lookups as `field=val → mapped=num (table)`, (3) profile fields consumed as `Collected: field=val, ...`, (4) confirmation gates as `CONFIRM_EXTRACTED_GATE: Holding [formulaRef], confirming: [fields]`. Multiple entries in one turn → list each. NOT user-facing."
    },
    "uiIntent": {
      "description": "Semantic UI intent. LLM emits field references, contextual content, and display intents. Backend projects onto palette components.",
      "type": "object",
      "required": ["message"],
      "properties": {

        "message": {
          "type": "string",
          "description": "Conversational text to the user. Always required."
        },

        "collect": {
          "type": "object",
          "description": "Populate when this turn needs user input. List the fields to collect.",
          "nullable": true,
          "required": ["fields"],
          "properties": {

            "formTitle": {
              "type": "string",
              "description": "Title for the input group when collecting multiple fields, e.g., 'Monthly Expenses', 'Income Details'. Populate when emitting 2+ fields.",
              "nullable": true
            },

            "fields": {
              "type": "array",
              "description": "Ordered list of fields to collect this turn. One field = standalone input. Multiple fields = grouped form.",
              "items": {
                "type": "object",
                "required": ["fieldRef", "entityMeta"],
                "properties": {

                  "fieldRef": {
                    "type": "string",
                    "description": "Field key. From coreFieldSchema for core fields, or from root-level jitFields for JIT fields."
                  },

                  "entityMeta": {
                    "type": "object",
                    "description": "Entity context for this field. Required for all fields — tells backend which entity instance to write to and how to qualify labels.",
                    "properties": {
                      "entityGroupId": {
                        "type": "string",
                        "description": "Entity group this field collects for (e.g., 'person_1', 'person_2', 'household_1')."
                      },
                      "relationshipToUser": {
                        "type": "string",
                        "enum": ["SELF", "SPOUSE", "PARENT", "CHILD", "HOUSEHOLD", "SIBLING", "OTHER"],
                        "description": "The entity's relationship to the primary user."
                      }
                    }
                  },

                  "title": {
                    "type": "string",
                    "description": "Contextual label. Omit to use the default label from coreFieldSchema.",
                    "nullable": true
                  },

                  "description": {
                    "type": "string",
                    "description": "Context explaining why this is being asked or what to include.",
                    "nullable": true
                  },

                  "exclusions": {
                    "type": "string",
                    "description": "What NOT to include, referencing other fields.",
                    "nullable": true
                  },

                  "placeholder": {
                    "type": "string",
                    "description": "Hint for text-mode input.",
                    "nullable": true
                  },

                  "optionDescriptions": {
                    "type": "array",
                    "description": "Per-option descriptions for choice fields needing explanatory context. Array order matches enumValues in coreFieldSchema.",
                    "nullable": true,
                    "items": { "type": "string" }
                  }
                }
              }
            }
          }
        },

        "present": {
          "type": "array",
          "description": "Display intents. Each entry becomes one display component.",
          "nullable": true,
          "items": {
            "type": "object",
            "required": ["resultKind", "title"],
            "properties": {

              "resultKind": {
                "type": "string",
                "enum": ["KPI", "PHASE_GATE", "STATUS", "CONFIRMATION", "ALLOCATION", "PLAN"],
                "description": "What this display block represents. KPI = computed target/score. PHASE_GATE = review collected data. STATUS = goal/plan state. CONFIRMATION = post-action receipt. ALLOCATION = proportional split. PLAN = savings timeline."
              },

              "entityMeta": {
                "type": "object",
                "description": "Entity context for this display block. Required when the display is entity-scoped (e.g., showing a specific person's results). Null for aggregate or plan-level displays.",
                "nullable": true,
                "properties": {
                  "entityGroupId": {
                    "type": "string",
                    "description": "Entity group this display relates to (e.g., 'person_1', 'household_1')."
                  },
                  "relationshipToUser": {
                    "type": "string",
                    "enum": ["SELF", "SPOUSE", "PARENT", "CHILD", "HOUSEHOLD", "SIBLING", "OTHER"],
                    "description": "The entity's relationship to the primary user."
                  }
                }
              },

              "title": {
                "type": "string",
                "description": "Card header. Conversational and specific."
              },

              "icon": {
                "type": "string",
                "description": "Emoji representing the domain.",
                "nullable": true
              },

              "headline": {
                "type": "object",
                "description": "Hero value display. Required for KPI, STATUS, CONFIRMATION. Optional for PHASE_GATE.",
                "nullable": true,
                "required": ["value", "subtitle"],
                "properties": {
                  "value": { "type": "string", "description": "Formatted primary value, e.g., '₹2,40,000'." },
                  "subtitle": { "type": "string", "description": "Contextual qualifier, e.g., '~6 months of essential expenses'." }
                }
              },

              "itemsHeader": {
                "type": "string",
                "description": "Section header above items, e.g., 'How we got here', 'Your milestones'.",
                "nullable": true
              },

              "items": {
                "type": "array",
                "description": "Data rows. Interpretation depends on resultKind. PHASE_GATE: field-value pairs. KPI: attribution factors. ALLOCATION: proportional segments. PLAN: timeline milestones. STATUS/CONFIRMATION: state rows.",
                "nullable": true,
                "items": {
                  "type": "object",
                  "required": ["label", "value"],
                  "properties": {
                    "label": {
                      "type": "string",
                      "description": "Row name: field label, factor name, segment name, or milestone name."
                    },
                    "value": {
                      "type": "string",
                      "description": "Primary content: formatted amount, date, impact, or display value."
                    },
                    "key": {
                      "type": "string",
                      "description": "Field identifier for edit routing. Populate for PHASE_GATE items.",
                      "nullable": true
                    },
                    "detail": {
                      "type": "string",
                      "description": "Secondary text: explanation, vehicle/instrument, or milestone amount.",
                      "nullable": true
                    },
                    "indicator": {
                      "type": "string",
                      "description": "Directional or status signal: UP, DOWN, NEUTRAL, UPCOMING, REACHED.",
                      "nullable": true
                    },
                    "icon": {
                      "type": "string",
                      "description": "Emoji for this item. Populate for ALLOCATION segments.",
                      "nullable": true
                    },
                    "shortLabel": {
                      "type": "string",
                      "description": "Abbreviated label for constrained surfaces. Populate for ALLOCATION bar segments.",
                      "nullable": true
                    }
                  }
                }
              },

              "statusBadge": {
                "type": "object",
                "description": "Status indicator. For STATUS resultKind.",
                "nullable": true,
                "properties": {
                  "label": { "type": "string", "description": "E.g., 'On Track', 'At Risk'." },
                  "statusTone": { "type": "string", "enum": ["POSITIVE", "CAUTIONARY", "NEUTRAL", "NEGATIVE"] }
                }
              },

              "primaryCta": {
                "type": "object",
                "nullable": true,
                "required": ["label", "intent"],
                "properties": {
                  "label": { "type": "string" },
                  "intent": {
                    "type": "string",
                    "enum": ["CONFIRM", "ACKNOWLEDGE", "EDIT", "EXPLORE"],
                    "description": "CONFIRM = affirm reviewed data. ACKNOWLEDGE = absorbed information. EDIT = revise inputs. EXPLORE = explore scenario."
                  }
                }
              },

              "secondaryCta": {
                "type": "object",
                "nullable": true,
                "required": ["label", "intent"],
                "properties": {
                  "label": { "type": "string" },
                  "intent": {
                    "type": "string",
                    "enum": ["CONFIRM", "ACKNOWLEDGE", "EDIT", "EXPLORE"]
                  }
                }
              }
            }
          }
        }
      }
    },
    "jitFields": {
      "type": "array",
      "description": "New field definitions not in coreFieldSchema. Emit ONCE per JIT field when first introduced. Null or empty on turns that introduce no new fields.",
      "nullable": true,
      "items": {
        "type": "object",
        "required": ["key", "dataType", "shortLabel"],
        "properties": {

          "key": {
            "type": "string",
            "description": "Slugified unique field ID, e.g., 'expected_wedding_cost'. Use this as fieldRef in uiIntent.collect and in planDelta.step.collected."
          },
          "dataType": {
            "type": "string",
            "enum": ["TEXT", "INTEGER", "LONG", "FLOAT", "BOOLEAN", "DATE"],
            "description": "Primitive data type."
          },
          "shortLabel": {
            "type": "string",
            "description": "Concise user-facing label, e.g., 'Wedding Budget'."
          },

          "unit": {
            "type": "string",
            "enum": ["INR", "PERCENT", "YEARS", "MONTHS", "DAYS", "COUNT"],
            "description": "Measurement unit. Provide for all numeric fields.",
            "nullable": true
          },
          "period": {
            "type": "string",
            "enum": ["MONTHLY", "QUARTERLY", "ANNUAL", "ONE_TIME"],
            "description": "Temporal period for monetary/rate fields.",
            "nullable": true
          },
          "description": {
            "type": "string",
            "description": "Internal context for LLM continuity on subsequent turns. Describe field boundaries and non-obvious aspects — what's included, what's excluded, edge cases. Not user-facing.",
            "nullable": true
          },
          "infotip": {
            "type": "string",
            "description": "User-facing help text shown on tap/hover. Concisely state what to consider and what NOT to consider when filling this field.",
            "nullable": true
          },
          "descriptiveLabel": {
            "type": "string",
            "description": "Longer-form label when shortLabel needs elaboration.",
            "nullable": true
          },
          "smartDefault": {
            "type": "number",
            "description": "Reasonable pre-filled value when domain knowledge supports one.",
            "nullable": true
          },
          "min": { "type": "number", "nullable": true },
          "max": { "type": "number", "nullable": true },
          "step": { "type": "number", "nullable": true },
          "options": {
            "type": "array",
            "nullable": true,
            "description": "Selection options for choice-type fields. Values must be reasonable, grounded, and mutually exclusive — not speculative or overlapping.",
            "items": {
              "type": "object",
              "required": ["value", "label"],
              "properties": {
                "value": { "type": "string" },
                "label": { "type": "string" },
                "description": { "type": "string", "nullable": true },
                "infotip": { "type": "string", "nullable": true },
                "icon": { "type": "string", "nullable": true }
              }
            }
          }
        }
      }
    },
    "planObject": {
      "type": "object",
      "description": "FULL plan. Emitted ONLY in MODE 1 (initial compilation) and MODE 4 (scenario creation). Null on all other turns — use planDelta instead.",
      "nullable": true,
      "properties": {
        "planId": {
          "type": "string",
          "description": "Descriptive slug: 'ef-setup-v1', 'scenario-city-move-bangalore'."
        },
        "goal": {
          "type": "string"
        },
        "successCondition": {
          "type": "string"
        },
        "overviewRef": {
          "type": "string",
          "description": "overviewId of the APPROVED planOverview. Null for scenario plans."
        },
        "phases": {
          "type": "array",
          "description": "Hierarchical phase structure. Each phase contains its own steps[] array.",
          "items": {
            "type": "object",
            "required": [
              "id",
              "title",
              "description",
              "status",
              "steps"
            ],
            "properties": {
              "id": {
                "type": "string"
              },
              "title": {
                "type": "string"
              },
              "description": {
                "type": "string"
              },
              "status": {
                "type": "string",
                "enum": [
                  "PENDING",
                  "ACTIVE",
                  "COMPLETED"
                ]
              },
              "steps": {
                "type": "array",
                "description": "Lean step records. Planning context only.",
                "items": {
                  "type": "object",
                  "required": [
                    "stepId",
                    "action"
                  ],
                  "properties": {
                    "stepId": {
                      "type": "string"
                    },
                    "action": {
                      "type": "string",
                      "enum": [
                        "ASK_INPUT",
                        "COMPUTE",
                        "SHOW_RESULT",
                        "RECOMMEND",
                        "CONFIRM_ACTION",
                        "CONFIRM_EXTRACTED"
                      ]
                    },
                    "collected": {
                      "type": "array",
                      "description": "ASK_INPUT only. entityGroupId.fieldName:formulaRole triples for each collected field. E.g., ['person_1.monthlyNetIncome:income.self', 'person_2.monthlyNetIncome:income.spouse', 'household_1.monthlyRent:expense.rent'].",
                      "nullable": true,
                      "items": {
                        "type": "string"
                      }
                    },
                    "formulaRef": {
                      "type": "string",
                      "description": "COMPUTE only. The formulaRecipe variable name being computed. E.g., 'burnRate', 'riskMultiplier', 'finalTarget'.",
                      "nullable": true
                    }
                  }
                }
              }
            }
          }
        },
        "planningVariables": {
          "type": "array",
          "description": "Plan-scoped computed values. Ephemeral.",
          "nullable": true,
          "items": {
            "type": "object",
            "required": [
              "name",
              "value",
              "source"
            ],
            "properties": {
              "name": {
                "type": "string"
              },
              "value": {
                "type": "number"
              },
              "source": {
                "type": "string",
                "enum": [
                  "COMPUTED",
                  "MAPPING",
                  "ASK_INPUT",
                  "JOURNEY_DERIVED"
                ]
              },
              "computedAt": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "planDelta": {
      "type": "object",
      "description": "Incremental update to the stored planObject. Emitted in MODE 2 and MODE 3. Backend merges this into the stored planObject. Mutually exclusive with planObject — never emit both.",
      "nullable": true,
      "properties": {
        "planId": {
          "type": "string",
          "description": "ID of the stored plan this delta applies to. Must match planObject.planId."
        },
        "phaseId": {
          "type": "string",
          "description": "ID of the ACTIVE phase to append the new step to."
        },
        "step": {
          "type": "object",
          "description": "The new lean step to append to the phase's steps[].",
          "required": [
            "stepId",
            "action"
          ],
          "properties": {
            "stepId": {
              "type": "string"
            },
            "action": {
              "type": "string",
              "enum": [
                "ASK_INPUT",
                "COMPUTE",
                "SHOW_RESULT",
                "RECOMMEND",
                "CONFIRM_ACTION",
                "CONFIRM_EXTRACTED"
              ]
            },
            "collected": {
              "type": "array",
              "description": "ASK_INPUT only. entityGroupId.fieldName:formulaRole triples for each collected field. E.g., ['person_1.monthlyNetIncome:income.self', 'person_2.monthlyNetIncome:income.spouse', 'household_1.monthlyRent:expense.rent'].",
              "nullable": true,
              "items": {
                "type": "string"
              }
            },
            "formulaRef": {
              "type": "string",
              "description": "COMPUTE only. The formulaRecipe variable name being computed. E.g., 'burnRate', 'riskMultiplier', 'finalTarget'.",
              "nullable": true
            }
          }
        },
        "phaseUpdates": {
          "type": "array",
          "description": "Phase status changes. Only include phases whose status changed this turn. Omit if no boundary crossed.",
          "nullable": true,
          "items": {
            "type": "object",
            "required": [
              "phaseId",
              "status"
            ],
            "properties": {
              "phaseId": {
                "type": "string"
              },
              "status": {
                "type": "string",
                "enum": [
                  "PENDING",
                  "ACTIVE",
                  "COMPLETED"
                ]
              }
            }
          }
        },
        "newVariables": {
          "type": "array",
          "description": "Planning variables computed this turn. Backend appends to planObject.planningVariables.",
          "nullable": true,
          "items": {
            "type": "object",
            "required": [
              "name",
              "value",
              "source"
            ],
            "properties": {
              "name": {
                "type": "string"
              },
              "value": {
                "type": "number"
              },
              "source": {
                "type": "string",
                "enum": [
                  "COMPUTED",
                  "MAPPING",
                  "ASK_INPUT",
                  "JOURNEY_DERIVED"
                ]
              },
              "computedAt": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "goalMutation": {
      "type": "object",
      "description": "Goal create, update, or lifecycle action for backend persistence. Null when no goal change this turn.",
      "nullable": true,
      "required": [
        "action"
      ],
      "properties": {
        "action": {
          "type": "string",
          "enum": [
            "CREATE",
            "UPDATE"
          ],
          "description": "CREATE for new goals. UPDATE when goal properties change."
        },
        "goalRef": {
          "type": "string",
          "description": "For UPDATE: existing goal ID from T1 portfolio. For CREATE: null (backend assigns).",
          "nullable": true
        },
        "identity": {
          "type": "object",
          "description": "§1 Identity fields. On CREATE: name and type required. On UPDATE: only changed fields.",
          "nullable": true,
          "properties": {
            "name": {
              "type": "string",
              "nullable": true
            },
            "type": {
              "type": "string",
              "enum": [
                "PROTECTION",
                "LIFE_EVENT",
                "WEALTH",
                "DEBT",
                "TAX"
              ],
              "nullable": true
            },
            "subtype": {
              "type": "string",
              "nullable": true,
              "description": "Finer categorization within type. E.g. 'home_purchase', 'wedding', 'car' for LIFE_EVENT."
            },
            "source": {
              "type": "string",
              "enum": [
                "USER_EXPLICIT",
                "JOURNEY_OUTCOME",
                "AI_DETECTED",
                "IMPORTED"
              ],
              "nullable": true
            },
            "tags": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true
            }
          }
        },
        "target": {
          "type": "object",
          "description": "§2 Target fields. Amount as string with ₹ prefix. Horizon as freeform text + structural type.",
          "nullable": true,
          "properties": {
            "amount": {
              "type": "string",
              "nullable": true,
              "description": "Target amount with ₹ prefix. E.g. '₹3,20,000'. Backend parses to rupees."
            },
            "horizonRaw": {
              "type": "string",
              "nullable": true,
              "description": "Freeform temporal expression. E.g. 'by 2028', 'within 3 years', 'before daughter turns 18'."
            },
            "horizonType": {
              "type": "string",
              "enum": [
                "DATE",
                "RELATIVE",
                "MILESTONE",
                "RECURRING",
                "OPEN"
              ],
              "nullable": true,
              "description": "Structural classification of the horizon. Backend uses this to attempt resolution to a concrete date."
            }
          }
        },
        "goalContext": {
          "type": "object",
          "description": "§5 Goal Context — the goal's memory. Reasoning state, portfolio graph, user preferences, and emotional signals.",
          "nullable": true,
          "properties": {
            "confidence": {
              "type": "string",
              "enum": [
                "LOW",
                "MEDIUM",
                "HIGH"
              ],
              "nullable": true
            },
            "negotiability": {
              "type": "string",
              "enum": [
                "FIXED",
                "FLEX_AMOUNT",
                "FLEX_TIMELINE",
                "FULLY_FLEXIBLE"
              ],
              "nullable": true
            },
            "assumptions": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true,
              "description": "What the AI assumed for projections. E.g. '12% equity returns', '6% inflation'."
            },
            "conflicts": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true,
              "description": "Goal IDs competing for same resources."
            },
            "dependsOn": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true,
              "description": "Goal IDs that should be completed first."
            },
            "priority": {
              "type": "integer",
              "nullable": true,
              "description": "Portfolio ordering. Lower = higher priority."
            },
            "notes": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true,
              "description": "Catch-all AI observations."
            },
            "userPreferences": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true,
              "description": "Append-only. User choices that constrain future advice. E.g. 'Rejected 12-month horizon'."
            },
            "emotionalSignals": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "nullable": true,
              "description": "Append-only. Emotional context for re-engagement tone. E.g. 'Expressed anxiety about job stability'."
            }
          }
        }
      }
    },
    "rerouteToOverview": {
      "type": "boolean",
      "description": "Set to true ONLY on major GOAL_CHANGE in MODE 3 (DEVIATION_REPLAN). Signals BE to start a new overview cycle. When true, planObject must be null.",
      "nullable": true
    }
  }
}
